import type {TomeRound,TomeStage} from './TomeFeature';
import type {SpinResult,Win} from './SlotMain';

export interface TomePlaybackStage extends Omit<TomeStage,'wins'> {
 clusters:TomeStage['wins'];wins:Win[];
}
export interface TomePlayback {
 mode:TomeRound['mode'];eyes:number[];opened:number[];charge:number;
 effectsAwarded:number;stages:TomePlaybackStage[];
}
export function tomeSymbol(id:string,symbol:number):string{
 if(!Number.isInteger(symbol)||symbol< -1||symbol>10)throw Error('Invalid Tome symbol');
 return id+'-'+(symbol<0?'void':symbol===8?'wild':symbol===9?'multiplier':symbol===10?'mega':symbol);
}
/** Every displayed award is the same object as the corresponding settlement
 * entry. Purchase normalization may change amounts, never feature history. */
export function tomeResult(id:string,bet:number,round:TomeRound):SpinResult{
 const stages:TomePlaybackStage[]=round.stages.map(stage=>{
  if(stage.awards.length!==stage.wins.length||stage.payout!==stage.awards.reduce((sum,n)=>sum+n,0))throw Error('Tome stage payout mismatch');
  const wins:Win[]=stage.wins.map((cluster,index)=>({line:-1,symbol:tomeSymbol(id,cluster.symbol),cells:[...cluster.cells],amount:stage.awards[index],multiplier:cluster.multiplier}));
  return{...stage,awards:[...stage.awards],clusters:stage.wins,wins};
 });
 const wins=stages.flatMap(stage=>stage.wins);
 if(wins.reduce((sum,win)=>sum+win.amount,0)!==round.payout)throw Error('Tome round payout mismatch');
 return{bet,openingBoard:round.opening.map(symbol=>tomeSymbol(id,symbol)),board:round.board.map(symbol=>tomeSymbol(id,symbol)),wins,payout:round.payout,
  tomeFeature:{mode:round.mode,eyes:[...round.eyes],opened:[...round.opened],charge:round.charge,effectsAwarded:round.effectsAwarded,stages},
  freeSpinsRemaining:round.mode==='other-world'?0:undefined,
  roundLabel:round.mode==='other-world'?'이세계 · 포털 효과':undefined,
 };
}
export function tomeSequenceResult(id:string,bet:number,base:TomeRound,bonus?:TomeRound):SpinResult{
 if(base.mode!=='base'||bonus&&bonus.mode!=='other-world')throw Error('Invalid Tome phase order');
 const first=tomeResult(id,bet,base);
 if(!bonus)return first;
 if(!base.effectsAwarded)throw Error('Tome bonus has no qualifying portal');
 const second=tomeResult(id,bet,bonus),rounds=[first,second];
 return{bet,board:[...second.board],rounds,wins:rounds.flatMap(round=>round.wins),payout:first.payout+second.payout,
  freeSpinsAwarded:1,featureName:'이세계 · 포털 효과 '+base.effectsAwarded+'개'};
}
