import {SlotMain,SpinResult} from './SlotMain';
import {social2230Slots} from './Social2230Registry';
import {socialSeed} from './Social1921Rules';
import {AngelDevilSlot} from './AngelDevilSlot';
/** Isolated free playback only; never changes production draws or wallet. */
export function social2230Audit(id:string,params:URLSearchParams):SlotMain|undefined{
 const slot=social2230Slots().find(s=>s.config.id===id);if(!slot)return;
 const outcome=params.get('audit-outcome');if(!outcome)return slot;
 slot.demoSpin=bet=>{
  const rng=socialSeed(223030),key=id+':'+bet;
  if(slot instanceof AngelDevilSlot&&outcome==='multi-win')slot.setProgress({});
  if(slot instanceof AngelDevilSlot&&['contract-loss','contract-top'].includes(outcome)){
   slot.setProgress({[key]:outcome==='contract-loss'?[1,2,0,bet*5]:[3,2,1,bet*5]});
   return slot.resolve(id+'-'+(outcome==='contract-loss'?4:0),bet);
  }
  const choice=Math.max(0,Math.min(2,Number(params.get('audit-choice'))||0));
  if('setProgress'in slot){
   if(outcome==='mission-expire')slot.setProgress({[key]:[0,0,1]});
   if(outcome==='equipment')slot.setProgress({[key]:[2,0,0]});
   if(outcome==='battle')slot.setProgress({[key]:[2,1,choice]});
  }
  const matches=(r:SpinResult)=>outcome==='rescue-fail'?!!r.rounds&&r.payout===0:
   outcome==='mission-expire'?!!r.ballroomFeature?.expired:
   outcome==='equipment'?!!r.featureChoices:
   outcome==='battle'?!!r.freeSpinsAwarded:
   (!r.rounds||id==='angel-devil-contract')&&(outcome==='no-win'?r.payout===0:outcome==='single-win'?r.wins.length===1:r.wins.length>1);
  for(let n=0;n<100000;n++){
   const r=slot.spin(bet,rng);if(matches(r))return r;
   // A fresh contract cannot complete a four-stamp path. Follow real continue
   // outcomes between draws so the audit can observe secured + bank awards.
   if(slot instanceof AngelDevilSlot&&outcome==='multi-win'){
    const next=r.featureChoices?.results[1]||r;
    if(next.progressUpdate)slot.setProgress({[key]:next.progressUpdate.values});
   }
  }
  throw Error('Natural 22–30 audit outcome unavailable: '+outcome);
 };
 return slot;
}
