const totals=():QuestTotals=>({all:stats(),slots:{}});
export const newQuestState=():QuestState=>({version:1,days:{},lifetime:totals(),dailyCompleted:0,allDays:0,tiers:{},earnedCoins:0,paidCoins:0});
export const questDay=(now:number)=>new Date(now+9*3600000).toISOString().slice(0,10);
const dayNumber=(id:string)=>Math.floor(Date.parse(id+'T00:00:00Z')/QUEST_DAY_MS);
