import {ExpansionSlot,randomIndex} from './ExpansionCore';
import {ExpansionSpec} from './ExpansionCatalog';
/** Local five-line adaptation: participating bear WILD opens ten independent free games. */
export class WhitePeakSlot extends ExpansionSlot {
 constructor(spec:ExpansionSpec){super(spec);this.config.symbols.find(s=>s.id===this.id('scatter'))!.weight=0;}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-polar';}
 get bonusSymbol(){return this.id('wild');}
 private qualifying(board:string[],bet:number){return Array.from(new Set(this.evaluate(board,bet).wins.flatMap(w=>w.cells).filter(c=>board[c]===this.id('wild'))));}
 private freeGames(base:ReturnType<ExpansionSlot['ordinary']>,bet:number,rng:()=>number){const rounds=[base];for(let left=9;left>=0;left--){const b=this.draw(bet,rng),r=this.ordinary(b,bet);r.freeSpinsRemaining=left;rounds.push(r);}return this.finish(rounds,{freeSpinsAwarded:10,featureOnly:false});}
 play(board:string[],bet:number,rng:()=>number){const base=this.ordinary(board,bet),bears=this.qualifying(board,bet);if(!bears.length)return this.finish([base]);base.expansionFeature!.frames.push(this.frame(board,'trigger','당첨 라인 흰 곰 · 무료 10회',bears));return this.freeGames(base,bet,rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){
  // The entry board is an explicit presentation fixture, not a claimed conditional natural draw.
  // No entry-board payout/progress affects the independently sampled free rounds.
  const board=this.draw(bet,rng),line=this.paylines[randomIndex(rng,this.paylines.length)],id=this.id(randomIndex(rng,8));line.slice(0,3).forEach(c=>board[c]=id);board[line[1]]=this.id('wild');const base=this.round(bet,[this.frame(board,'trigger','독립 무료 10회 구매',line.slice(0,3))]);return this.purchaseFromResult(this.freeGames(base,bet,rng));
 }
}
