/** Half the final paid-round win multiple, stored in tenths of a ticket. */
export function winTickets(payout:number,bet:number){
 if(!Number.isFinite(payout)||!Number.isFinite(bet)||bet<=0)return 0;
 const multiple=payout/bet;if(multiple<=0)return 0;
 return Math.min(1000,Math.max(1,Math.floor(multiple*5)));
}
