import type {Win} from './SlotMain';

export type CompassMode='free'|'wild'|'repeat'|'multiply'|'pick'|'upgrade'|'prize';
export type CompassWheel='main'|'quantity'|'reward';
export interface CompassTurn {wheel:CompassWheel;index:number;label:string;}
export interface CompassPlayback {
 turns:CompassTurn[]; mode:CompassMode; quantity:number;
 sourceCells:number[]; transformedCells:number[]; awards:Win[];
}
export const COMPASS_MODES:readonly CompassMode[]=['free','wild','repeat','multiply','pick','upgrade','prize'];
export const COMPASS_LABELS=['무료 항해','나침반 WILD','반복 보상','배수 항해','선택 나침반','강화 나침반','보물 나침반'];
export const COMPASS_QUANTITIES=[2,3,4,5] as const;
export const COMPASS_REWARDS=[2,3,5,8,12,20] as const;
/** Each draw is a separate recorded stop; a child wheel cannot precede its parent.
 * These probabilities and values are our own design, not copied source math. */
export function drawCompass(sourceCells:number[],rng:()=>number):CompassPlayback {
 const pick=(length:number)=>{const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid compass RNG');return Math.floor(value*length);};
 const main=pick(COMPASS_MODES.length),mode=COMPASS_MODES[main],q=pick(COMPASS_QUANTITIES.length),quantity=COMPASS_QUANTITIES[q];
 const turns:CompassTurn[]=[{wheel:'main',index:main,label:COMPASS_LABELS[main]},{wheel:'quantity',index:q,label:String(quantity)}];
 if(mode==='upgrade'||mode==='prize'){const reward=pick(COMPASS_REWARDS.length);turns.push({wheel:'reward',index:reward,label:String(COMPASS_REWARDS[reward])});}
 return {turns,mode,quantity,sourceCells:[...sourceCells],transformedCells:[],awards:[]};
}
export function compassReward(feature:CompassPlayback):number {
 const stop=feature.turns.find(turn=>turn.wheel==='reward');
 if(!stop)return 0;
 return COMPASS_REWARDS[stop.index]*(feature.mode==='upgrade'?feature.quantity:1);
}
