import {Node,UITransform,Graphics,Color,BlockInputEvents} from 'cc';
import {networkWait} from '../services/NetworkWait';

/** Independent of screen rebuilds, with no network activity of its own. */
export class NetworkWaitOverlay {
 private root:Node|null=null;private spinner:Node|null=null;private width=0;private height=0;
 constructor(private parent:Node){}
 update(dt:number,width:number,height:number){
  if(!networkWait.delayed){this.destroy();return;}
  if(!this.root||this.width!==width||this.height!==height){
   this.destroy();this.width=width;this.height=height;
   const root=this.root=new Node('Delayed server response overlay');root.layer=this.parent.layer;this.parent.addChild(root);
   root.addComponent(UITransform).setContentSize(width,height);root.addComponent(BlockInputEvents);
   const shade=root.addComponent(Graphics);shade.fillColor=new Color(0,0,0,179);shade.rect(-width/2,-height/2,width,height);shade.fill();
   const spinner=this.spinner=new Node('Network waiting spinner');spinner.layer=root.layer;root.addChild(spinner);
   const g=spinner.addComponent(Graphics);
   for(let i=0;i<12;i++){const angle=i*Math.PI/6;g.fillColor=new Color(255,255,255,40+i*19);g.circle(Math.cos(angle)*25,Math.sin(angle)*25,4);g.fill();}
  }
  this.spinner!.angle-=dt*240;this.root.setSiblingIndex(this.parent.children.length-1);
 }
 destroy(){this.root?.destroy();this.root=null;this.spinner=null;}
}
