import {ExpansionSlot,ExpansionFrame,Geometry,expansionCells as cells,randomIndex} from './ExpansionCore';
import {SpinResult} from './SlotMain';
import {drawThreeGateBoard} from './ConditionalGateBoard';

export const FROG_CHAPTERS=['연못의 편지','낯선 왕관','정원의 약속','잃어버린 반지','도서관의 비밀','달빛 무도회','성문 앞 선택','장미의 단서','거울 속 진실','마지막 열쇠','왕자의 고백','새로운 이야기'];
export const STORY_BUILDS=[{count:32,multiplier:.25,label:'32회 · 베팅 ¼'},{count:16,multiplier:.5,label:'16회 · 베팅 ½'},{count:8,multiplier:1,label:'8회 · 베팅 ×1'}] as const;
/** Local story progression and boosted-spin adaptation of Get Me a Prince. */
export class FrogStorySlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]) {
  super(spec);
  const seen=new Set(this.paylines.map(line=>line.join(',')));
  for(let code=0;this.paylines.length<50&&code<243;code++){
   let n=code;const line=Array.from({length:5},(_,col)=>{const row=n%3;n=Math.floor(n/3);return row*5+col;});
   if(!seen.has(line.join(','))){seen.add(line.join(','));this.paylines.push(line);}
  }
  for(const [name,weight] of [['page',1],['portrait',0],['double',0],['boost',0]] as const)this.config.symbols.push({id:this.id(name),name,color:'#efd08c',weight,payout:0});
 }
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-story';}
 isWild(id:string){return super.isWild(id)||id===this.id('double');}
 private pool(col:number,free=false,seen=false){return this.config.symbols.filter(s=>s.weight>0&&!(free&&s.id===this.id('page'))&&!(seen&&s.id===this.id('scatter')));}
 private weighted(rng:()=>number,pool:{id:string;weight:number}[]){let roll=rng()*pool.reduce((n,s)=>n+s.weight,0);for(const s of pool){roll-=s.weight;if(roll<0)return s.id;}return pool[pool.length-1].id;}
 private grid(bet:number,rng:()=>number,free=false,story=false){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const b:string[]=[];
  for(let c=0;c<15;c++){
   let id=this.weighted(rng,this.pool(c%5,free,b.some((s,i)=>i%5===c%5&&s===this.id('scatter'))).filter(s=>!(story&&s.id===this.id('scatter'))&&!(s.id===this.id('page')&&b.some((id,i)=>i%5===c%5&&id===s.id))));
   if(free&&id===this.id('wild')&&rng()<.25)id=this.id('double');
   b.push(id);
  }
  return b;
 }
 draw(bet:number,rng:()=>number,_g:Geometry=this.geometry){return this.grid(bet,rng);}
 private reelRound(input:string[],bet:number,state:number[],storyMultiplier=0){
  const b=[...input],frames:ExpansionFrame[]=[this.frame(b,'reels',storyMultiplier?'이야기 부스터 · 낮은 심볼을 WILD로':'왕자와 공주의 릴')];
  if(storyMultiplier){const changed=b.flatMap((id,c)=>[4,5,6,7].some(n=>id===this.id(n))?[c]:[]);for(const c of changed){b[c]=this.id('wild');}if(changed.length)frames.push(this.frame(b,'effect','낮은 심볼 → WILD',changed));}
  const values=b.map(id=>id===this.id('double')?2:1);
  frames.push(this.hit(b,bet,storyMultiplier?'이야기 당첨 ×'+storyMultiplier:'개구리 WILD · 당첨 참여 배수',this.geometry,{values,wildMode:'product',awardMultiplier:storyMultiplier||1}));
  for(const frame of frames)frame.panel={label:FROG_CHAPTERS[state[0]],values:[state[0],state[1]],columns:2};
  return this.round(bet,frames);
 }
 private journey(base:SpinResult,bet:number,rng:()=>number,state:number[],normalCount:number,storyMode?:number){
  const rounds=[JSON.parse(JSON.stringify(base)) as SpinResult];let remaining=normalCount,awarded=normalCount;
  while(remaining>0&&awarded<=200){
   remaining--;const b=this.grid(bet,rng,true),r=this.reelRound(b,bet,state),gate=cells(b,this.id('scatter')),added=gate.length>=3?Math.min(10,200-awarded):0;
   if(added){remaining+=added;awarded+=added;r.freeSpinsAdded=added;r.expansionFeature!.frames.push(this.frame(b,'trigger','키스 3개 · 무료 +10회',gate));}
   r.freeSpinsRemaining=remaining+(storyMode===undefined?0:STORY_BUILDS[storyMode].count);rounds.push(r);
  }
  if(storyMode!==undefined){const build=STORY_BUILDS[storyMode];for(let left=build.count-1;left>=0;left--){const r=this.reelRound(this.grid(bet,rng,true,true),bet,state,build.multiplier);r.freeSpinsRemaining=left;r.roundLabel='STORY · ×'+build.multiplier;rounds.push(r);}}
  return this.finish(rounds,{freeSpinsAwarded:normalCount+(storyMode===undefined?0:STORY_BUILDS[storyMode].count),featureOnly:false});
 }
 play(board:string[],bet:number,rng:()=>number){
  const state=this.state(bet,[0,0]),chapter=state[0],pages=cells(board,this.id('page')),before=state[1];state[1]+=pages.length;
  const base=this.reelRound(board,bet,[chapter,before]),frames=base.expansionFeature!.frames;
  if(pages.length)frames.push(this.frame(board,'collect','이야기 책갈피 → 다음 장',pages,{meter:{label:'이야기 '+(chapter+1)+'장',before,after:state[1],target:10,items:pages.map(cell=>({cell,value:1}))},panel:{label:FROG_CHAPTERS[chapter],values:[chapter,state[1]],columns:2}}));
  const gates=cells(board,this.id('scatter')),normal=gates.length>=3?10:0;
  if(normal)frames.push(this.frame(board,'trigger','키스 3개 · 무료 10회',gates));
  if(state[1]>=10){
   state[1]-=10;state[0]=(chapter+1)%12;
   frames.push(this.frame(board,'trigger',FROG_CHAPTERS[chapter]+' · 이야기 보상 선택',pages,{actor:{symbol:this.id(1),cells:pages}}));
   const branches=STORY_BUILDS.map((_,mode)=>this.progressResult(this.journey(base,bet,rng,state,normal,mode),bet,state));
   return this.choices(FROG_CHAPTERS[chapter]+' · 이야기 부스터',STORY_BUILDS.map(x=>x.label),branches);
  }
  return this.progressResult(normal?this.journey(base,bet,rng,state,normal):this.finish([base]),bet,state);
 }
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const b=drawThreeGateBoard(col=>this.pool(col),this.id('scatter'),rng,(r,p)=>this.weighted(r,p));
  const base=this.round(bet,[this.frame(b,'trigger','키스 3개 · 독립 무료 10회',cells(b,this.id('scatter')))]);
  return this.purchaseFromResult(this.journey(base,bet,rng,[0,0],10));
 }
}
