import {BlackoutSlot} from './BlackoutSlot';
export function blackoutAudit(params:URLSearchParams){const slot=new BlackoutSlot(),outcome=params.get('audit-outcome');if(outcome)slot.demoSpin=bet=>{let seed=399280;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<300000;i++){const r=slot.spin(bet,rng),rounds=r.rounds||[r],f=rounds[0].blackoutFeature!,injected=f.injections.flatMap(s=>s.cells),match=outcome==='dual'?f.injections.length===2:outcome==='dual-role'?injected.some(c=>f.before[c]===slot.config.id+'-wild'):outcome==='injection'?f.injections.length>0&&!!r.rounds:outcome==='natural'?f.naturalBlue.length+f.naturalYellow.length>=5:outcome==='sticky'?rounds.some(x=>x.blackoutFeature!.heldBefore.length>0):outcome==='retrigger'?rounds.some(x=>!!x.freeSpinsAdded):outcome==='no-win'?!r.rounds&&r.wins.length===0:outcome==='single-win'?!r.rounds&&r.wins.length>0&&new Set(r.wins.map(w=>w.symbol)).size===1:outcome==='multi-win'?!r.rounds&&new Set(r.wins.map(w=>w.symbol)).size>1:false;if(match)return r;}throw Error('Blackout natural fixture unavailable');};return slot;}
