import {RhinoBoard,rhinoEvaluate} from './RhinoRules';
/** Dedicated art order follows the source paytable, not atlas position. */
export const RHINO_ART=['cheetah','gorilla','crocodile','hyena','flamingo','rank_a','rank_k','rank_q','rank_j','rank_10','rhino','rhino_token'] as const;
export interface RhinoCellView {cell:number;symbol:number;art:string;reel:number;row:number;top:boolean;x:number;y:number;width:number;height:number;}
/** Coordinates are fractions of the complete reel area, origin top-left.
 * The independent horizontal strip occupies the middle four columns. Main
 * columns fill the same vertical area with2..7 symbols of different heights.
 * The1/8 strip allocation is our proposed layout, not an original pixel measurement. */
export function rhinoLayout(board:RhinoBoard):RhinoCellView[]{
 rhinoEvaluate(board,20); // Shared source-layout validation, never normalized.
 const width=1/6,topHeight=1/8,cells:RhinoCellView[]=[];
 const make=(cell:number,symbol:number,reel:number,row:number,top:boolean,x:number,y:number,height:number):RhinoCellView=>({cell,symbol,art:'slot-art-delivered-v1/rhino-grand-ways/v07/'+RHINO_ART[symbol],reel,row,top,x,y,width,height});
 board.columns.forEach((column,reel)=>{
  const height=(1-topHeight)/column.length;
  column.forEach((symbol,row)=>cells.push(make(reel*7+row,symbol,reel,row,false,reel*width,topHeight+row*height,height)));
 });
 board.top.forEach((symbol,i)=>cells.push(make(42+i,symbol,i+1,0,true,(i+1)*width,0,topHeight)));
 return cells;
}
/** Resolve hit cell IDs through actual variable-height geometry. Never use
 * row-major modulo arithmetic inherited from the fixed rectangular slots. */
export function rhinoHitViews(board:RhinoBoard,hitCells:readonly number[]){
 const views=new Map(rhinoLayout(board).map(cell=>[cell.cell,cell]));
 return [...Array.from(new Set(hitCells))].map(id=>{const view=views.get(id);if(!view)throw Error('Rhino hit references an absent cell');return view;});
}
