import {Node,UITransform,Graphics,Color,Label,Sprite,SpriteFrame,Font,Vec3,tween,BlockInputEvents} from 'cc';
import {ToyPlayback} from '../slots/ToyDefendersSlot';
import {i18n} from '../services/Localization';
import {formatAmount} from '../services/AmountFormat';

/** Presentation only: targets and awards always come from the settled result. */
export class ToyDefensePanel {
 readonly node:Node;
 private robots=new Map<number,Node>();
 private round:Label;private remaining:Label;private status:Label;private reward:Label;
 private marker:Node;private tool:Node;private y:number;private x:number;private w:number;private h:number;private pitch:number;
 constructor(parent:Node,width:number,height:number,contentX:number,private frames:Map<string,SpriteFrame>,private font:Font|null,tool:number){
  this.node=new Node('Toy defense persistent stage');this.node.layer=parent.layer;parent.addChild(this.node);this.node.setPosition(-width/2,-height/2);
  this.x=contentX+24;this.w=width-contentX*2-48;this.h=Math.min(710,height-260);this.y=height-(height-this.h)/2;this.pitch=(this.w-48)/5;
  const dim=this.rect('Dim',0,height,width,height,'#000000',128);const dimBounds=dim.addComponent(UITransform);dimBounds.setAnchorPoint(0,1);dimBounds.setContentSize(width,height);dim.addComponent(BlockInputEvents);
  this.rect('Defense panel',this.x,this.y,this.w,this.h,'#172c37');
  this.rect('Header',this.x+8,this.y-8,this.w-16,106,'#28414c');
  this.label('ui.toy.goal',this.x+18,this.y-18,this.w-36,48,23);
  this.round=this.label('',this.x+18,this.y-72,this.w*.48,32,20);
  this.remaining=this.label('',this.x+this.w*.5,this.y-72,this.w*.46,32,20);
  const fieldTop=this.y-130,fieldH=this.h-300;
  for(let col=0;col<5;col++)this.rect('Robot lane '+col,this.x+24+col*this.pitch,fieldTop,this.pitch-3,fieldH,'#243d47');
  this.rect('Defense line',this.x+18,fieldTop-fieldH,this.w-36,4,'#e9bc70');
  for(let col=0;col<5;col++)this.art('barricade',this.x+24+(col+.5)*this.pitch,fieldTop-fieldH-22,48,48);
  this.tool=this.art(['magnet','hammer','net'][tool],this.x+this.w/2,this.y-this.h+100,66,66);
  this.label(['ui.robot.toolMagnet','ui.robot.toolHammer','ui.robot.toolNet'][tool],this.x+18,this.y-this.h+136,this.w*.36,62,18);
  this.status=this.label('',this.x+18,this.y-this.h+60,this.w-36,28,20);
  this.reward=this.label('',this.x+18,this.y-this.h+31,this.w-36,26,19);
  this.marker=this.rect('Round progress',this.x+12,this.y-this.h+5,0,3,'#83dccb');
 }
 private rect(name:string,x:number,y:number,w:number,h:number,color:string,alpha=255){const n=new Node(name);n.layer=this.node.layer;this.node.addChild(n);n.setPosition(x,y);const g=n.addComponent(Graphics);const c=new Color(color);c.a=alpha;g.fillColor=c;g.rect(0,-h,w,h);g.fill();return n;}
 private label(key:string,x:number,y:number,w:number,h:number,size:number){const n=new Node('Defense '+key);n.layer=this.node.layer;this.node.addChild(n);n.setPosition(x,y);const t=n.addComponent(UITransform);t.setAnchorPoint(0,1);const l=n.addComponent(Label);l.string=key?i18n.t(key):'';if(this.font)l.font=this.font;l.fontSize=size;l.lineHeight=size*1.2;l.color=new Color('#fff0c9');l.horizontalAlign=Label.HorizontalAlign.CENTER;l.verticalAlign=Label.VerticalAlign.CENTER;l.overflow=Label.Overflow.SHRINK;t.setContentSize(w,h);return l;}
 private art(id:string,x:number,y:number,w:number,h:number){const n=new Node('Defense '+id);n.layer=this.node.layer;this.node.addChild(n);n.setPosition(x,y);n.addComponent(UITransform).setContentSize(w,h);const s=n.addComponent(Sprite);s.sizeMode=Sprite.SizeMode.CUSTOM;s.spriteFrame=this.frames.get('toy-bonus/'+id)!;return n;}
 private point(id:number,advance:number){const size=Math.min(56,this.pitch*.7),fieldH=this.h-300,step=Math.max(0,(fieldH-size*4-8)/10);return new Vec3(this.x+24+(id%5+.5)*this.pitch,this.y-130-size/2-Math.floor(id/5)*size-advance*step,0);}
 private motion(n:Node,seconds:number,props:object){return new Promise<void>(resolve=>{tween(n).to(seconds,props).call(()=>resolve()).start();});}
 async play(f:ToyPlayback,pay:(amount:number)=>Promise<void>){
  this.node.setSiblingIndex(this.node.parent!.children.length-1);
  this.round.string=i18n.t('ui.toy.round',{round:f.round});this.remaining.string=i18n.t('ui.toy.remaining',{count:f.before.length});this.reward.string='';
  this.status.string=i18n.t('ui.toy.target',{count:f.targets.length});
  for(const id of f.before)if(!this.robots.has(id)){const p=this.point(id,f.advanceBefore),n=this.art('robot',p.x,p.y,Math.min(56,this.pitch*.7),Math.min(56,this.pitch*.7));this.robots.set(id,n);}
  const color=['#86dfcf','#f49c80','#d5b2ff'][f.tool],origin=this.tool.position.clone();
  for(const id of f.targets){
   const target=this.robots.get(id)!;
   const outline=this.rect('Selected robot',target.position.x-28,target.position.y+28,56,56,color,90);
   const shot=this.art(['magnet','hammer','net'][f.tool],origin.x,origin.y,42,42);
   await this.motion(shot,.18,{position:target.position.clone()});
   await this.motion(target,.12,{scale:new Vec3(1.2,1.2,1)});
   shot.destroy();outline.destroy();target.destroy();this.robots.delete(id);
   this.remaining.string=i18n.t('ui.toy.remaining',{count:this.robots.size});
  }
  await Promise.all(f.after.map(id=>this.motion(this.robots.get(id)!, .24,{position:this.point(id,f.advanceAfter)})));
  const g=this.marker.getComponent(Graphics)!;g.clear();g.fillColor=new Color(color);g.rect(0,-3,(this.w-24)*f.round/10,3);g.fill();
  this.status.string=i18n.t(f.status==='cleared'?'ui.toy.cleared':f.status==='overrun'?'ui.toy.overrun':'ui.toy.stopped',{count:f.targets.length});
  for(const [index,win]of f.awards.entries()){
   this.reward.string=i18n.t(index>0?'ui.toy.clearPay':'ui.toy.attackPay',{amount:formatAmount(win.amount)});
   await pay(win.amount);
  }
 }
 destroy(){this.node.removeFromParent();this.node.destroy();}
}
