import {Social2230LineSlot,socialPresentation,sumResult,SOCIAL_2230_PAYS,awardLines,packRounds} from './Social2230Rules';
import {SpinResult,Win} from './SlotMain';
import {socialSeed} from './Social1921Rules';
export const ZODIAC_FREE_SPINS:Readonly<Record<number,number>>={3:8,4:10,5:15};
export const ZODIAC_JACKPOTS=[2,5,10,20,50] as const;
export interface ZodiacPlayback {mode:'base'|'trigger'|'free';selected:number;cells:number[];awards:Win[];scatterCells?:number[];remaining?:number;jackpot?:{wildCells:number[];tier:number;award:Win};}
export class GoldenZodiacSlot extends Social2230LineSlot {
 readonly hasBonus=true;readonly bonusCalibrationKey='golden-zodiac-choice:free-v2';get bonusSymbol(){return this.config.id+'-scatter';}
 readonly selectionTitle='이 베팅에서 사용할 황금 별자리를 고르세요';readonly selectionLabels=['해시계','월식 고리','천체 망원경'];
 readonly presentation=socialPresentation('회전 전에 선택한 별자리만 황금 당첨','선택 별자리 두 배');
 readonly config=this.namedConfig('golden-zodiac-choice','황금 별자리 선택','GOLDEN ZODIAC CHOICE',['해시계','월식 고리','천체 망원경','천문판','성도 두루마리','관측종','측량 컴퍼스','혜성 깃발','황도 WILD'],'베팅별 첫 회전에 세 별자리 중 하나 선택. 이후 같은 베팅에서는 선택을 유지.\n선택 심볼의 당첨 라인만 ×2. 선택은 베팅별 저장.\n황도 바퀴 3/4/5개: 무료 8/10/15회. 2~4릴의 WILD는 5단계 고정 잭팟 기회를 엽니다.\n선택 후보 세 종류는 동일 등장률·배당으로 설계.','#252f4e','#dace86');
 constructor(){super();for(let n=0;n<3;n++){this.config.symbols[n].weight=6;this.config.symbols[n].payout=this.pays[0][2];}this.config.symbols.push({id:this.bonusSymbol,name:'황도 바퀴',color:'#dace86',weight:3,payout:0});}
 selectionForBet(bet:number){const n=this.state(bet,[0])[0];return n<3?n:0;}
 selectionRequiredForBet(bet:number){return !this.progress[this.config.id+':'+bet];}
 evaluate(board:string[],bet:number){
  if(!Number.isInteger(this.selection)||this.selection<0||this.selection>2)throw Error('Invalid zodiac selection');
  const r=super.evaluate(board,bet),pays=this.pays.map((row,n)=>row.map(v=>v*(n===this.selection?2:1)));
  r.wins=awardLines(this.config,board,bet,pays);const awards=r.wins.filter(w=>w.symbol===this.config.id+'-'+this.selection);
  r.zodiacFeature={mode:'base',selected:this.selection,cells:board.flatMap((id,c)=>id===this.config.id+'-'+this.selection?[c]:[]),awards};return sumResult(r);
 }
 private board(rng:()=>number){const symbols=this.config.symbols,out:string[]=[];for(let cell=0;cell<15;cell++){const col=cell%5,options=symbols.filter(symbol=>(symbol.id!==this.bonusSymbol||!out.some((id,c)=>c%5===col&&id===this.bonusSymbol))&&(symbol.id!==this.config.id+'-wild'||col>0&&col<4&&!out.some((id,c)=>c%5===col&&id===this.config.id+'-wild')));let roll=rng()*options.reduce((sum,symbol)=>sum+symbol.weight,0),picked=options.at(-1)!.id;for(const symbol of options){roll-=symbol.weight;if(roll<0){picked=symbol.id;break;}}out.push(picked);}return out;}
 private resolve(board:string[],bet:number,rng:()=>number,mode:'base'|'free'){
  const result=this.evaluate(board,bet),wildCells=board.flatMap((id,cell)=>id===this.config.id+'-wild'?[cell]:[]).slice(0,3);
  if(wildCells.length&&rng()<wildCells.length*.06){const roll=rng(),tier=roll<.5?0:roll<.78?1:roll<.92?2:roll<.98?3:4,multiplier=ZODIAC_JACKPOTS[tier],award:Win={line:-70,symbol:this.config.id+'-wild',cells:wildCells,amount:bet*multiplier,multiplier};result.wins.push(award);result.zodiacFeature!.jackpot={wildCells,tier,award};}
  result.zodiacFeature!.mode=mode;return sumResult(result);
 }
 private bonus(base:SpinResult,rng:()=>number,count:number,includeBase:boolean){const free:SpinResult[]=[];for(let spin=0;spin<count;spin++){const round=this.resolve(this.board(rng),base.bet,rng,'free');round.freeSpinsRemaining=count-spin-1;round.roundLabel='FREE SPINS · '+(spin+1)+'회';round.zodiacFeature!.remaining=count-spin-1;free.push(round);}return packRounds(includeBase?[base,...free]:free,{freeSpinsAwarded:count,featureName:'GOLDEN ZODIAC FREE SPINS',presentation:this.presentation});}
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');const base=this.resolve(this.board(rng),bet,rng,'base'),scatterCells=base.board.flatMap((id,cell)=>id===this.bonusSymbol?[cell]:[]),count=ZODIAC_FREE_SPINS[Math.min(5,scatterCells.length)]||0,progressUpdate=this.update(bet,[this.selection]);base.progressUpdate=progressUpdate;if(!count)return base;base.zodiacFeature!.mode='trigger';base.zodiacFeature!.scatterCells=scatterCells;return{...this.bonus(base,rng,count,true),progressUpdate};}
 prepareBonusPurchase(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');const board=this.board(rng);for(const cell of [0,7,14])board[cell]=this.bonusSymbol;const trigger:SpinResult={board,bet,wins:[],payout:0,roundLabel:'BONUS TRIGGER',zodiacFeature:{mode:'trigger',selected:this.selection,cells:[],awards:[],scatterCells:[0,7,14]},presentation:this.presentation},result=this.bonus(trigger,rng,8,false);result.bonusTriggerRound=trigger;return result;}

 get pays(){return SOCIAL_2230_PAYS.map((row,i)=>(i<3?SOCIAL_2230_PAYS[0]:row).map(n=>n*1.928));}
 demoSpin(bet:number){const rng=socialSeed(25+this.selection);for(let i=0;i<20000;i++){const r=this.spin(bet,rng);if(r.zodiacFeature!.awards.length)return r;}throw Error('Zodiac preview unavailable');}
}
