import {SlotMain,SlotConfig,SlotPresentation,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {TOME_PAYS,tomeClusters} from './TomeRules';
import {tomeGame} from './TomeGame';
import {tomeSymbol} from './TomeResult';

/** Dedicated portal/Other World engine, registered after free playback QA. */
export class TomeSlot extends SlotMain {
 readonly columns=5;readonly rows=5;readonly mode='clusters' as const;
 readonly hasBonus=true;readonly maxWin=2000;readonly bets=[...BET_LEVELS];readonly paylines:number[][]=[];
 readonly usesReferencePayouts=true;
 readonly bonusCalibrationKey='tome-of-madness:portal';
 readonly rules=['상하좌우 연결4개부터 총베팅 배당','책과 거대 수호자는 WILD · 참여 탐험가가 있으면 해당 클러스터×2(중복 없음)','제거 심볼7/14/27개 → 책2개 · ABYSS 행·열 연쇄 / VOID 한 종류 제거','포털42개 → 이세계1라운드 · 효과3개, 초과3개마다+1(최대7)','이세계 고정 눈11~12개 모두 개방 → 2×2거대 수호자 연속 하강','전체 당첨 상한 총베팅2000배'];
 readonly presentation:SlotPresentation={evidence:'official-rules',anticipationText:'포털 충전 · 42개를 모으세요',triggerText:'포털 개방 · 이세계',bonusInText:'이세계 · 포털 효과',hitText:'연결 당첨 · 포털 충전',totalWinText:'비밀의 서 · 총 당첨',signature:'포털 효과3~7개 · 눈 개방 시 거대 WILD',uiEffect:'책 공개 · ABYSS 경로 제거 · VOID 종류 제거 · 거대 수호자 연속 하강',soundCue:'featureLand',anticipationHold:.35,hitHold:.2,outHold:.6};
 readonly config:SlotConfig={id:'tome-of-madness',title:'비밀의 서',subtitle:'TOME OF SECRETS',tag:'PORTAL · OTHER WORLD',color:'#263d36',accent:'#8ee2bc',description:'상하좌우로 연결된 같은 심볼 4개부터 당첨\n제거 심볼 7/14/27개마다 포털 책과 특수 효과\n42개 → 이세계 1라운드 · 효과3~7개\n눈을 모두 열면 거대 수호자 등장',symbols:[
  ...['촉수 부적','의식 단검','고대 반지','유적 가면','보라 보석','붉은 보석','파랑 보석','초록 보석'].map((name,index)=>({id:tomeSymbol('tome-of-madness',index),name,art:index<4?['mask','sword','disc','mask'][index]:'gem',color:'#b7f0d6',weight:1,payout:TOME_PAYS[index][6]})),
  {id:'tome-of-madness-wild',name:'책 · WILD',art:'book',color:'#ffdc91',weight:0,payout:0},
  {id:'tome-of-madness-multiplier',name:'탐험가 · ×2 WILD',art:'boy',color:'#ffdc91',weight:0,payout:0},
  {id:'tome-of-madness-mega',name:'거대 수호자 · WILD',art:'mask',color:'#a5f9ce',weight:0,payout:0},
 ]};
 private present(result:SpinResult){result.presentation=this.presentation;result.rounds?.forEach(round=>round.presentation=this.presentation);return result;}
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid Tome bet');return this.present(tomeGame(bet,rng));}
 /** Low-symbol first cluster only. Full portal/eye history is still generated. */
 forceBaseHit(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid Tome bet');const board=Array.from({length:25},(_,i)=>(i+Math.floor(i/5)*2)%8);for(const cell of [0,1,5,6])board[cell]=7;return this.present(tomeGame(bet,rng,board));}
 evaluate(board:string[],bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid Tome bet');
  const values=board.map(id=>this.config.symbols.findIndex(symbol=>symbol.id===id));if(values.some(n=>n<0))throw Error('Invalid Tome symbol');
  const wins=tomeClusters(values).map(cluster=>({line:-1,symbol:tomeSymbol(this.config.id,cluster.symbol),cells:cluster.cells,multiplier:cluster.multiplier,amount:Math.round(bet*cluster.multiple)}));
  return{board:[...board],bet,wins,payout:wins.reduce((sum,win)=>sum+win.amount,0)};
 }
 demoSpin(bet:number){let seed=419;return this.forceBaseHit(bet,()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});}
 bonusDemoSpin(bet:number){let seed=90521;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<10000;i++){const result=this.spin(bet,rng);if(result.rounds)return result;}throw Error('Tome free bonus preview failed to find a portal');}
}
